// Create src/registry.ts if it does not exist yet.
//
// registry.ts is GENERATED by `video-studio build_props` from the props
// directory listing, so it names whatever projects a given machine has built
// and is deliberately not committed. But Root.tsx imports it, so on a fresh
// clone the composer cannot typecheck or open until build_props has run once —
// a chicken-and-egg that hits every new user before they have a project to
// build.
//
// Root.tsx already handles an EMPTY registry: it registers a stub composition
// that explains no project has been built yet. It just cannot survive a MISSING
// file. This writes the empty form so that path is reachable, and never
// overwrites a real one.
import { existsSync, writeFileSync } from "node:fs";

const path = new URL("./src/registry.ts", import.meta.url);

if (existsSync(path)) {
  process.exit(0);
}

writeFileSync(
  path,
  `// GENERATED — do not edit.
// Placeholder written by ensure-registry.mjs on install. Running
// \`video-studio build_props\` replaces this with one entry per built project.
import type { VideoProps } from "./Video";

export const PROJECTS: Record<string, VideoProps> = {};
`,
);
console.log("composer: wrote an empty src/registry.ts (build_props will replace it)");
